from pydantic import BaseModel, AfterValidator
from typing import Annotated

def _check_no_newlines(v: str | None) -> str | None:
    if v is not None and ("\n" in v or "\r" in v):
        raise ValueError("SSE field must not contain newlines")
    return v

class TestModel(BaseModel):
    event: Annotated[str | None, AfterValidator(_check_no_newlines)] = None
    id: Annotated[str | None, AfterValidator(_check_no_newlines)] = None

try:
    TestModel(event="hello\nworld")
except ValueError as e:
    print(f"Caught expected error for event: {e}")

try:
    TestModel(id="hello\rworld")
except ValueError as e:
    print(f"Caught expected error for id: {e}")

print("Tests passed")
EOF

